  document.querySelectorAll(".prose pre > code").forEach(code => {
    const pre = code.parentElement;
    const shell = /language-(bash|sh|shell|console)/.test(code.className);
    const raw = code.textContent;
    if (shell) {
      const esc = s => s.replace(/&/g, "&amp;").replace(/</g, "&lt;");
      code.innerHTML = raw.split("\n").map(line => {
        const m = line.match(/^(\$ )?(.*?)(\s+#.*)?$/);
        if (/^\s*#/.test(line)) return `<span class="tok-c">${esc(line)}</span>`;
        return (m[1] ? `<span class="tok-p">$ </span>` : "") + esc(m[2]) + (m[3] ? `<span class="tok-c">${esc(m[3])}</span>` : "");
      }).join("\n");
    }
    const btn = document.createElement("button");
    btn.type = "button"; btn.className = "copy"; btn.textContent = "Copy";
    btn.addEventListener("click", () => {
      let text = raw;
      if (shell) {  // copy commands only: no prompts, comments or output lines
        const lines = raw.split("\n");
        const prompted = lines.some(l => l.startsWith("$ "));
        text = lines.filter(l => (prompted ? l.startsWith("$ ") : !/^\s*#/.test(l)) && l.trim())
          .map(l => l.replace(/^\$ /, "").replace(/\s+#.*$/, "")).join("\n");
      }
      const done = label => { btn.textContent = label; setTimeout(() => { btn.textContent = "Copy"; }, 1400); };
      if (navigator.clipboard) navigator.clipboard.writeText(text.trim()).then(() => done("Copied"), () => done("Press ⌘C"));
    });
    pre.appendChild(btn);
  });

  // Mobile navigation.
  const menu = document.querySelector(".menu");
  menu?.addEventListener("click", () => {
    const open = document.body.classList.toggle("nav-open");
    menu.setAttribute("aria-expanded", String(open));
  });
  document.querySelectorAll(".sidebar a").forEach(a => a.addEventListener("click", () => document.body.classList.remove("nav-open")));

  // On this page: highlight the section in view.
  const links = [...document.querySelectorAll(".toc a")];
  const heads = links.map(a => document.getElementById(decodeURIComponent(a.hash.slice(1)))).filter(Boolean);
  if (heads.length && "IntersectionObserver" in window) {
    const seen = new Map();
    const io = new IntersectionObserver(entries => {
      entries.forEach(e => seen.set(e.target.id, e.isIntersecting));
      const current = heads.find(h => seen.get(h.id)) || null;
      if (current) links.forEach(a => a.classList.toggle("active", a.hash === "#" + current.id));
    }, { rootMargin: "-64px 0px -70% 0px" });
    heads.forEach(h => io.observe(h));
  }

  // Search over window.DOCS_INDEX (titles, headings and page text).
  const box = document.getElementById("search"), input = document.getElementById("search-input");
  const list = document.getElementById("search-results");
  const index = window.DOCS_INDEX || [];
  let sel = 0, results = [];
  const esc = s => s.replace(/&/g, "&amp;").replace(/</g, "&lt;");
  const mark = (s, q) => { const i = s.toLowerCase().indexOf(q); return i < 0 ? esc(s) : esc(s.slice(0, i)) + "<mark>" + esc(s.slice(i, i + q.length)) + "</mark>" + esc(s.slice(i + q.length)); };
  function search(q) {
    q = q.trim().toLowerCase();
    if (!q) return index.slice(0, 8).map(p => ({ url: p.url, title: p.title, sub: p.group }));
    const out = [];
    index.forEach(p => {
      if (p.title.toLowerCase().includes(q)) out.push({ url: p.url, title: p.title, sub: p.group, score: 3 });
      p.headings.forEach(([id, h]) => { if (h.toLowerCase().includes(q)) out.push({ url: `${p.url}#${id}`, title: h, sub: p.title, score: 2 }); });
      const i = p.text.toLowerCase().indexOf(q);
      if (i >= 0 && !out.some(r => r.url === p.url)) out.push({ url: p.url, title: p.title, sub: "…" + p.text.slice(Math.max(0, i - 40), i + 80) + "…", score: 1 });
    });
    return out.sort((a, b) => b.score - a.score).slice(0, 12);
  }
  function draw() {
    const q = input.value.trim().toLowerCase();
    results = search(input.value);
    sel = Math.min(sel, Math.max(0, results.length - 1));
    list.innerHTML = results.length ? results.map((r, i) =>
      `<li class="${i === sel ? "sel" : ""}"><a href="${r.url}">${mark(r.title, q)}<small>${mark(r.sub, q)}</small></a></li>`).join("")
      : `<li class="empty">No results for “${esc(input.value)}”. Try a command name, like <code>init</code> or <code>drift</code>.</li>`;
  }
  function open() { box.hidden = false; input.value = ""; sel = 0; draw(); input.focus(); }
  function close() { box.hidden = true; }
  document.getElementById("search-open")?.addEventListener("click", open);
  box?.addEventListener("click", e => { if (e.target === box) close(); });
  input?.addEventListener("input", () => { sel = 0; draw(); });
  input?.addEventListener("keydown", e => {
    if (e.key === "ArrowDown") { sel = Math.min(sel + 1, results.length - 1); draw(); e.preventDefault(); }
    if (e.key === "ArrowUp") { sel = Math.max(sel - 1, 0); draw(); e.preventDefault(); }
    if (e.key === "Enter" && results[sel]) { location.href = results[sel].url; close(); }
  });
  document.addEventListener("keydown", e => {
    const typing = /INPUT|TEXTAREA/.test(document.activeElement?.tagName || "");
    if ((e.key === "/" && !typing) || (e.key.toLowerCase() === "k" && (e.metaKey || e.ctrlKey))) { e.preventDefault(); open(); }
    if (e.key === "Escape" && !box.hidden) close();
  });
})();

