def topbar(extra: str = "") -> str:
    return ('<header class="top"><button class="menu-toggle" type="button">Menu</button>'
            '<span class="logo"><i></i>Culprit docs</span>' + extra +
            '<button class="search" type="button">Search docs   /</button></header>')


def build() -> None:
    side_std = primary_links() + sequence() + more() + collapsed()
    designs = {
        "terminal": ("Docs A Terminal Steps", "family=Geist:wght@400;500;600;700&family=Geist+Mono:wght@400;500;600", CSS1,
                     topbar() + f'<div class="shell"><aside class="side">{side_std}</aside><main class="main">{HEAD}{content("terminal")}</main></div>'),
        "paper": ("Docs B Paper", "family=Public+Sans:wght@400;600;700;800&family=JetBrains+Mono:wght@400;600", CSS2,
                  topbar() + f'<div class="shell"><aside class="side">{side_std}</aside><main class="main">{HEAD}{content("slab")}</main></div>'),
        "tabs": ("Docs C Tabs", "family=Instrument+Sans:wght@400;500;600;700&family=Fira+Code:wght@400;500;600", CSS3,
                 topbar() + '<nav class="tabs"><a class="on" href="#">Guide</a><a href="#">Commands</a><a href="#">Concepts</a><a href="#">Reference</a><a href="#">Help</a></nav>'
                 + f'<div class="shell"><aside class="side">{primary_links() + sequence() + more() + collapsed()}</aside><main class="main">{HEAD}{content("rail")}</main></div>'),
        "split": ("Docs D Split", "family=Atkinson+Hyperlegible:wght@400;700&family=IBM+Plex+Mono:wght@400;600", CSS4,
                  topbar() + f'<div class="shell"><aside class="side">{side_std}</aside><main class="main"><div class="head">{HEAD}'
                  f'<p>{PAGE[0][1]}</p></div>{content("rail").split("</p>", 1)[1]}</main></div>'),
        "focus": ("Docs E Focus", "family=Figtree:wght@400;500;600;700&family=Martian+Mono:wght@400;500;600", CSS5,
                  topbar() + f'<div class="shell"><aside class="side">{side_std}</aside><main class="main"><div class="inner">{HEAD}{content("rail")}</div></main></div>'),
    }
    for slug, (name, fonts, css, body) in designs.items():
        (OUT / f"{slug}.html").write_text(page(name, fonts, css, body))
    print("wrote", ", ".join(designs))


